import{_ as a,C as d,o as n,c as s,aj as e,E as o}from"./framework.js";const b=JSON.parse('{"title":"Tax | Commerce | Admin CMS","description":"Configure commerce tax by country/region: one rule per country with base tax rate, optional regional overrides for provinces/states, and product condition overrides. Cart trial and order…","frontmatter":{"title":"Tax | Commerce | Admin CMS","description":"Configure commerce tax by country/region: one rule per country with base tax rate, optional regional overrides for provinces/states, and product condition overrides. Cart trial and order…","head":[["link",{"rel":"canonical","href":"https://docs.kooboo.com/cms/commerce/taxes.html"}]]},"headers":[],"relativePath":"cms/commerce/taxes.md","filePath":"en/cms/commerce/taxes.md","lastUpdated":1781010536000}'),i={name:"cms/commerce/taxes.md"};function c(l,t,g,m,u,h){const r=d("DocImage");return n(),s("div",null,[t[0]||(t[0]=e('<h1 id="tax" tabindex="-1">Tax <a class="header-anchor" href="#tax" aria-label="Permalink to &quot;Tax&quot;">​</a></h1><blockquote><p>Menu: <strong>Commerce -&gt; Tax</strong><br> Deep link: <code>/_Admin/commerce/taxes?SiteId={siteGuid}</code><br><strong>Create</strong>: <code>/_Admin/commerce/taxes/create?SiteId=...&amp;country={countryName}</code><br><strong>Edit</strong>: <code>/_Admin/commerce/taxes/edit?SiteId=...&amp;id={taxRuleId}</code></p></blockquote><p>Configure commerce <strong>tax</strong> by <strong>country/region</strong>: one rule per country with <strong>base tax rate</strong>, optional <strong>regional overrides</strong> for provinces/states, and <strong>product condition</strong> overrides. Cart trial and <a href="./orders.html">order</a> checkout match rates by shipping country/region and products (line <code>taxAmount</code>, order tax total).</p><div class="tip custom-block"><p class="custom-block-title">Permission</p><p>Menu permission feature name is <code>tax</code> (not <code>taxes</code>); edit requires <code>tax</code> · <code>edit</code>.</p></div><h2 id="how-to-open" tabindex="-1">How to Open <a class="header-anchor" href="#how-to-open" aria-label="Permalink to &quot;How to Open&quot;">​</a></h2><ol><li>In the <a href="./../navigation.html#edit-menu">Edit menu</a>, enable <strong>Commerce -&gt; Tax</strong> (and the parent <strong>Commerce</strong> group).</li><li>Open <strong>Commerce -&gt; Tax</strong> in the left sidebar.</li></ol><h2 id="list-page" tabindex="-1">List Page <a class="header-anchor" href="#list-page" aria-label="Permalink to &quot;List Page&quot;">​</a></h2><p>Path: <code>/_Admin/commerce/taxes?SiteId=...</code></p><table tabindex="0"><thead><tr><th>Column / Action</th><th>Description</th></tr></thead><tbody><tr><td><strong>Country</strong></td><td>Flag + localized country name (Commerce country library)</td></tr><tr><td><strong>Base tax</strong></td><td><code>baseTax</code>, percentage display</td></tr><tr><td><strong>Create</strong></td><td>Opens <strong>Select country</strong> dialog; already configured countries excluded</td></tr><tr><td><strong>Edit</strong></td><td>Row pencil → <a href="#create-and-edit">create and edit</a></td></tr><tr><td><strong>Batch delete</strong></td><td>Select rows → <strong>Delete</strong> → confirm</td></tr></tbody></table>',9)),o(r,{src:"/cms/commerce/taxes-list.png",alt:"Tax rules list: country and base rate",width:"1120"}),t[1]||(t[1]=e('<h3 id="select-country-dialog" tabindex="-1">Select Country Dialog <a class="header-anchor" href="#select-country-dialog" aria-label="Permalink to &quot;Select Country Dialog&quot;">​</a></h3><p>After <strong>Create</strong>, select country without tax rule yet; keyword filter supported; click table row to enter create page (query <code>country</code>). Dialog is <code>SelectCountryDialog</code>: search box + country table (name, code).</p><div class="tip custom-block"><p class="custom-block-title">Create button permission</p><p>List <strong>Create</strong> button uses permission <code>taxes</code> · <code>edit</code>, while menu registers <code>tax</code> · <code>edit</code>. If button shows disabled &quot;no permission&quot;, accounts with tax edit permission can still access <code>taxes/create?SiteId=...&amp;country={countryName}</code> directly.</p></div><h2 id="create-and-edit" tabindex="-1">Create and Edit <a class="header-anchor" href="#create-and-edit" aria-label="Permalink to &quot;Create and Edit&quot;">​</a></h2><p>Create path includes <code>country</code>; edit path includes <code>id</code>. Breadcrumb: <strong>Tax -&gt; {country name}</strong>. Shared <code>EditForm</code>, bottom <strong>Save</strong> / <strong>Cancel</strong> returns to list.</p>',5)),o(r,{src:"/cms/commerce/taxes-edit.png",alt:"Tax rule edit: base tax, regional and product overrides",width:"1120"}),t[2]||(t[2]=e('<h3 id="base-tax" tabindex="-1">Base Tax <a class="header-anchor" href="#base-tax" aria-label="Permalink to &quot;Base Tax&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Description</th></tr></thead><tbody><tr><td><strong>Base tax</strong></td><td><code>baseTax</code>, percentage number (<code>ElInputNumber</code>, step 0.1, min 0)</td></tr></tbody></table><h3 id="regional-overrides" tabindex="-1">Regional Overrides <a class="header-anchor" href="#regional-overrides" aria-label="Permalink to &quot;Regional Overrides&quot;">​</a></h3><p>When country has <strong>provinces/states</strong> etc. in Commerce address library, <strong>Regional overrides</strong> card appears:</p><table tabindex="0"><thead><tr><th>Capability</th><th>Description</th></tr></thead><tbody><tr><td><strong>Search</strong></td><td>Filter regions by keyword</td></tr><tr><td><strong>Reset</strong></td><td>Clear keyword and remove all regional override entries</td></tr><tr><td><strong>Pagination</strong></td><td>6 regions per page</td></tr><tr><td><strong>Per-region rate</strong></td><td>Percentage + <strong>calculation method</strong> dropdown</td></tr></tbody></table><p>Calculation methods (<code>OverridesType</code>) — copy includes current base tax <code>{tax}%</code>:</p><table tabindex="0"><thead><tr><th>Value</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>Added</strong></td><td><strong>Add</strong> this percentage on top of base tax</td></tr><tr><td><strong>Instead</strong></td><td><strong>Replace</strong> base tax; use only this percentage</td></tr><tr><td><strong>Compounded</strong></td><td><strong>Compound</strong> on base tax (multiplication logic on server)</td></tr></tbody></table><p>Regions without override use <strong>base tax</strong>.</p><h3 id="product-overrides" tabindex="-1">Product Overrides <a class="header-anchor" href="#product-overrides" aria-label="Permalink to &quot;Product Overrides&quot;">​</a></h3><p><strong>Product overrides</strong> can add multiple rules, each containing:</p><table tabindex="0"><thead><tr><th>Item</th><th>Description</th></tr></thead><tbody><tr><td><strong>Rate</strong></td><td>Percentage</td></tr><tr><td><strong>Calculation method</strong></td><td>Added / Instead / Compounded relative to &quot;base tax + matched regional override&quot; (similar copy to regional overrides, referencing regional result)</td></tr><tr><td><strong>Conditions</strong></td><td><code>Condition</code> component: match <strong>product</strong> dimension fields (schema from <code>getTaxSchemas</code>), AND/OR multiple rules</td></tr><tr><td><strong>Done</strong></td><td>Click <strong>Done</strong> while editing to collapse to summary; click summary to expand again</td></tr><tr><td><strong>Delete</strong></td><td>Remove this product override</td></tr><tr><td><strong>Add</strong></td><td>Round <strong>+</strong> adds new rule</td></tr></tbody></table><p>Matching product lines use override rate at trial/checkout; otherwise fall back to regional/base tax.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./orders.html">Orders</a> — line tax and order tax total</li><li><a href="./carts.html">Carts</a> — checkout mode trial includes tax</li><li><a href="./currencies.html">Currencies</a>, <a href="./settings.html">Settings</a></li><li><a href="/kb-docs/api/commerce/commerce.html">k.commerce</a> (<code>taxAmount</code> in cart/order trial)</li></ul>',14))])}const x=a(i,[["render",c]]);export{b as __pageData,x as default};
